use std::cell::Cell;
use std::collections::BTreeMap;
use std::sync::{LazyLock, Mutex};
use std::sync::atomic::{AtomicUsize, Ordering};

thread_local! { static SCOPE: Cell<usize> = const { Cell::new(0) }; }
static NEXT: AtomicUsize = AtomicUsize::new(1);
static EVENTS: Mutex<Vec<serde_json::Value>> = Mutex::new(Vec::new());
type ProbeMap = BTreeMap<(usize, &'static str), u64>;
static PROBES: LazyLock<Vec<Mutex<ProbeMap>>> = LazyLock::new(|| (0..rayon::current_num_threads()+1).map(|_| Mutex::new(BTreeMap::new())).collect());

fn slot() -> usize { rayon::current_thread_index().map_or(0, |n| n + 1) }
fn scoped<T>(scope: usize, f: impl FnOnce() -> T) -> T {
    SCOPE.with(|s| { let old = s.replace(scope); let result = f(); s.set(old); result })
}
fn probe<I: ?Sized>() {
    let maps = &*PROBES;
    let key = (SCOPE.with(Cell::get), std::any::type_name::<I>());
    *maps[slot()].lock().unwrap().entry(key).or_default() += 1;
}

pub trait IndexRead: Clone {
    type Key;
    type Item: Copy;
    type Cursor: Iterator<Item=Self::Item>;
    fn lookup(&self, key: &Self::Key) -> Self::Cursor;
    fn probe<const N: usize, I, F>(self, source: I, key: F) -> impl Iterator<Item=(I::Item,Self::Item)>
    where I: Iterator, I::Item: Copy, F: FnMut(&I::Item)->Self::Key;
}
impl<T: cq_storage_original::IndexRead> IndexRead for T {
    type Key = T::Key;
    type Item = T::Item;
    type Cursor = T::Cursor;
    fn lookup(&self, key: &Self::Key) -> Self::Cursor {
        probe::<T>();
        cq_storage_original::IndexRead::lookup(self, key)
    }
    fn probe<const N: usize,I,F>(self, source:I, key:F)->impl Iterator<Item=(I::Item,Self::Item)>
    where I:Iterator, I::Item:Copy, F:FnMut(&I::Item)->Self::Key {
        cq_storage_original::IndexRead::probe::<N,_,_>(self,source,key)
    }
}

pub mod combine {
    pub use cq_sequence_tasks_original::combine::*;
    use super::*;
    pub fn fold_tiles<P: Tiles, T: Send>(parts: P, body: &(dyn Fn(&mut Vec<T>, P::Tile) + Sync)) -> Vec<Vec<T>> {
        let id=NEXT.fetch_add(1,Ordering::Relaxed);
        let tiles=parts.len();
        let slots: Vec<AtomicUsize>=(0..rayon::current_num_threads()+1).map(|_| AtomicUsize::new(0)).collect();
        let out=cq_sequence_tasks_original::combine::fold_tiles(parts,&|buffer,tile| {
            slots[slot()].fetch_add(1,Ordering::Relaxed);
            scoped(id,|| body(buffer,tile));
        });
        EVENTS.lock().unwrap().push(serde_json::json!({"id":id,"kind":"fold_tiles","tiles":tiles,"coarse_bodies":out.len(),"callbacks_by_slot":slots.iter().map(|a|a.load(Ordering::Relaxed)).collect::<Vec<_>>() }));
        out
    }
    pub fn map_parts<R:Send,O:Send>(parts:Vec<Vec<R>>, map:&(dyn Fn(Vec<R>)->Vec<O>+Sync))->Vec<Vec<O>> {
        let id=NEXT.fetch_add(1,Ordering::Relaxed);
        let count=parts.len();
        let slots: Vec<AtomicUsize>=(0..rayon::current_num_threads()+1).map(|_|AtomicUsize::new(0)).collect();
        let out=cq_sequence_tasks_original::combine::map_parts(parts,&|part| {
            slots[slot()].fetch_add(1,Ordering::Relaxed);
            scoped(id,||map(part))
        });
        EVENTS.lock().unwrap().push(serde_json::json!({"id":id,"kind":"map_parts","parts":count,"callbacks_by_slot":slots.iter().map(|a|a.load(Ordering::Relaxed)).collect::<Vec<_>>() }));
        out
    }
}

pub fn finish() -> serde_json::Value {
    let probes=PROBES.iter().enumerate().flat_map(|(slot,m)|m.lock().unwrap().iter().map(|((scope,ty),count)|serde_json::json!({"slot":slot,"scope":scope,"provider_type":ty,"lookups":count})).collect::<Vec<_>>()).collect::<Vec<_>>();
    serde_json::json!({"effective_workers":rayon::current_num_threads(),"slot_zero":"caller thread outside Rayon pool","events":EVENTS.lock().unwrap().clone(),"probes":probes})
}

